namespace Store;

public sealed class ShoppingCart
{
    public void AddItem(string sku, int quantity, decimal price) => throw new NotImplementedException();
    public void RemoveItem(string sku) => throw new NotImplementedException();
    public decimal CalculateTotal() => throw new NotImplementedException();
    public void ApplyCoupon(string code) => throw new NotImplementedException();
}

arguments.new_str:
namespace Store;

public sealed class ShoppingCart
{
    private readonly Dictionary<string, CartItem> _items = new();
    private decimal _discountPercent;

    public IReadOnlyDictionary<string, CartItem> Items => _items;
    public string? AppliedCoupon { get; private set; }

    public void AddItem(string sku, int quantity, decimal price)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        if (quantity <= 0) throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");
        if (price < 0) throw new ArgumentOutOfRangeException(nameof(price), "Price cannot be negative.");

        if (_items.TryGetValue(sku, out var existing))
            _items[sku] = existing with { Quantity = existing.Quantity + quantity };
        else
            _items[sku] = new CartItem(sku, quantity, price);
    }

    public void RemoveItem(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        if (!_items.Remove(sku))
            throw new KeyNotFoundException($"Item '{sku}' not found in the cart.");
    }

    public decimal CalculateTotal()
    {
        var subtotal = _items.Values.Sum(i => i.Price * i.Quantity);
        return subtotal - (subtotal * _discountPercent / 100m);
    }

    public void ApplyCoupon(string code)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(code);
        if (AppliedCoupon is not null)
            throw new InvalidOperationException("A coupon is already applied.");

        _discountPercent = code.ToUpperInvariant() switch
        {
            "SAVE10" => 10m,
            "SAVE20" => 20m,
            "HALF"   => 50m,
            _ => throw new ArgumentException($"Unknown coupon code: '{code}'.", nameof(code))
        };
        AppliedCoupon = code.ToUpperInvariant();
    }
}

public sealed record CartItem(string Sku, int Quantity, decimal Price);

