using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ── AddItem ────────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(2, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantitiesAccumulate()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 5.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_BothAppearInCart()
    {
        _sut.AddItem("A", 1, 10.00m);
        _sut.AddItem("B", 2, 20.00m);

        Assert.AreEqual(2, _sut.Items.Count);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_NonPositiveQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", quantity, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -0.01m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _sut.AddItem("FREE", 1, 0m);

        Assert.AreEqual(0m, _sut.Items["FREE"].Price);
    }

    // ── RemoveItem ─────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 5.00m);
        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(
            () => _sut.RemoveItem("GHOST"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void RemoveItem_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetItem()
    {
        _sut.AddItem("A", 1, 1.00m);
        _sut.AddItem("B", 1, 2.00m);
        _sut.RemoveItem("A");

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.IsTrue(_sut.Items.ContainsKey("B"));
    }

    // ── CalculateTotal ─────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsPriceTimesQuantity()
    {
        _sut.AddItem("SKU-1", 3, 10.00m);

        Assert.AreEqual(30.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 5.00m);   // 10.00
        _sut.AddItem("B", 1, 15.00m);  // 15.00

        Assert.AreEqual(25.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemove_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 1, 10.00m);
        _sut.AddItem("B", 1, 20.00m);
        _sut.RemoveItem("A");

        Assert.AreEqual(20.00m, _sut.CalculateTotal());
    }

    // ── ApplyCoupon ────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_AppliesToTotal(string code, int discountPercent)
    {
        _sut.AddItem("A", 1, 100.00m);
        _sut.ApplyCoupon(code);

        var expected = 100.00m - (100.00m * discountPercent / 100m);
        Assert.AreEqual(expected, _sut.CalculateTotal());
        Assert.AreEqual(code.ToUpperInvariant(), _sut.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _sut.AddItem("A", 1, 100.00m);
        _sut.ApplyCoupon("save10");

        Assert.AreEqual(90.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_AlreadyApplied_ThrowsInvalidOperation()
    {
        _sut.ApplyCoupon("SAVE10");

        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.ApplyCoupon("SAVE20"));
    }

    // ── Combined scenarios ─────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponCalculateTotal()
    {
        _sut.AddItem("WIDGET", 2, 25.00m);  // 50.00
        _sut.AddItem("GADGET", 1, 50.00m);  // 50.00
        _sut.ApplyCoupon("SAVE20");          // 20% off

        Assert.AreEqual(80.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_NoDiscount()
    {
        _sut.AddItem("A", 1, 42.00m);

        Assert.IsNull(_sut.AppliedCoupon);
        Assert.AreEqual(42.00m, _sut.CalculateTotal());
    }
}

